"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Crumbs and Clues', 'author': 'Signature original', 'genre': 'Manor House Mysteries', 'chapters': [{'n': 1, 'title': 'Tea and Tidings', 'text': "The morning Harriet Wren found a pressed flower on the doorstep of her cottage in the riverside inn, the kettle had just begun to sing. She turned the object over in her hands, frowning, for it plainly belonged to someone — and someone in the riverside inn was missing it badly.\n\nBefore bed she wrote in her journal: Day one. The game is on. Tomorrow I walk the hedgerows and ask the questions no one else will ask. justice in small places — that is what this is about, though no one says so yet.\n\nConstable Henry Bly arrived before the tea was poured, full of the news: the silent partner had been seen about the riverside inn at dawn, asking questions nobody liked. 'Harriet Wren,' said Constable Henry Bly, 'there's a mystery brewing, and you're the only one with the nose for it.'"}, {'n': 2, 'title': 'The Missing Piece', 'text': "Harriet Wren began with the riverside inn itself, walking every lane with a pressed flower wrapped in a handkerchief. The hedgerows of the riverside inn had seen everything, she always said; one had only to ask the right people in the right order.\n\nConstable Henry Bly brought the parish records, and together they found the gap: a name missing where a name should be, a date that did not fit. a pressed flower was the key, Harriet Wren was certain; it unlocked a story someone had paid to keep shut.\n\nAt the riverside inn, the landlord remembered the silent partner drinking alone, turning a pressed flower over and over. 'Nervous hands,' he said. 'Guilty hands, if you ask me.' Harriet Wren asked him, and wrote it down."}, {'n': 3, 'title': 'Questions at Dusk', 'text': "At dusk she walked to the old vicarage alone, turning a pressed flower in her pocket. The answer, she felt, was close — as close as the church bell that began to toll, counting out the hours like clues.\n\nBack in the parlor, Harriet Wren laid out the evidence: the landlord's tale, the parish gap, the threatening note, the too-perfect description. Constable Henry Bly whistled. 'It's a noose,' they said, 'and the silent partner tied it.'\n\nHarriet Wren found the silent partner at the edge of the riverside inn, packing a bag in a great hurry. 'Leaving us?' she asked pleasantly, and the silent partner's smile did not reach the eyes. Every answer was smooth, and every smooth answer was a lie."}, {'n': 4, 'title': 'The Storm Breaks', 'text': "They went out in rain capes, lanterns swinging, and found the disturbed earth — and beneath it, not treasure, but proof: letters, a photograph, and the mate to a pressed flower. The whole sad story lay in the mud.\n\nHarriet Wren listened to the end, rain running off her cape. Justice, she said quietly, was not the same as punishment; but the truth belonged to everyone in the riverside inn, and it would be told.\n\nthe silent partner appeared then, wild-eyed, and confessed before Harriet Wren could speak: it had begun as a kindness, grown into a theft, and ended in a lie that poisoned the riverside inn. 'I never meant —' began the silent partner, and could not finish."}, {'n': 5, 'title': 'The Reckoning', 'text': 'That evening the kettle sang again in her cottage, and Harriet Wren wrote the last line in her journal: Truth told, justice done, neighbors mended. justice in small places — I shall drink tea to that.\n\na pressed flower was restored to its rightful keeper, who wept to hold it. Harriet Wren declined all thanks, as was her custom, and slipped away before the speeches. The case was closed; the village could breathe.\n\nOn market day Harriet Wren laid it all before the riverside inn: a pressed flower, the letters, the photograph, the confession. The crowd in the square was silent as a church. the silent partner stood with head bowed and did not deny a word.'}, {'n': 6, 'title': 'Quiet After', 'text': "the silent partner, from wherever the law had sent him, wrote a letter of thanks: for the truth, for the pity, for the chance to begin again. Harriet Wren read it twice and filed it with the case notes.\n\nConstable Henry Bly brought flowers — 'for the best detective in the county,' they said, gruff as ever. Harriet Wren put them in water and told them not to be silly, but she kept the card.\n\nAnd if another mystery comes to the riverside inn — as mysteries do, like weather — Harriet Wren will be ready, kettle on, journal open. For justice in small places, always, in the riverside inn and everywhere."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

